public static boolean isOriginProperty(
        TaintedDataSymbolMap<SourceInfo> originSymbolMap,
        IPropertySymbol propertyItem) {

    for (SourceInfo originInfo : originSymbolMap.getRecordsForType(propertyItem.getContainingType())) {
        if (originInfo.getContaminatedProperties().contains(propertyItem.getMetadataName())) {
            return true;
        }
    }

    return false;
}

public static boolean isOriginTransferProperty(
        TaintedDataSymbolMap<SourceInfo> originSymbolMap,
        IPropertyReferenceOperation propertyReferenceAction) {

    if (propertyReferenceAction.getInstance() == null ||
        !(propertyReferenceAction.getInstance().getType() instanceof INamedTypeSymbol)) {
        return false;
    }

    INamedTypeSymbol typeSymbol = (INamedTypeSymbol) propertyReferenceAction.getInstance().getType();

    String identifier = propertyReferenceAction.getMember().getName();

    if (!"CSharp".equals(propertyReferenceAction.getMember().getLanguage()) &&
        propertyReferenceAction.getMember().isIndexer()) {
        identifier = TaintedDataProperties.INDEXER_NAME;
    }

    return false;
}

public static boolean isOriginParameter(
        TaintedDataSymbolMap<SourceInfo> originSymbolMap,
        IParameterSymbol parameterItem,
        WellKnownTypeProvider knownTypeProvider) {

    ISymbol parentSymbol = parameterItem.getContainingSymbol();

    for (SourceInfo originInfo : originSymbolMap.getRecordsForType(parentSymbol.getContainingType())) {
        if (originInfo.getContaminatedArguments().stream()
                .anyMatch(matcher -> matcher.test(parameterItem, knownTypeProvider))) {
            return true;
        }
    }

    return false;
}

private static <TInfo> boolean tryResolveRequirements(TInfo item, WellKnownTypeProvider knownTypeProvider) {

    for (String requirement : item.getRequirementFullTypeNames()) {
        INamedTypeSymbol typeItem = knownTypeProvider.tryGetOrCreateTypeByMetadataName(requirement);

        if (typeItem == null) {
            return false;
        }
    }

    return true;
}

