static TaintedDataAbstractValue mergeContaminated(
        TaintedDataAbstractValue valueA,
        TaintedDataAbstractValue valueB) {

    assert valueA.getKind() == TaintedDataAbstractValueKind.TAINTED;
    assert valueB.getKind() == TaintedDataAbstractValueKind.TAINTED;

    ImmutableSet<SymbolAccess> combinedSources = 
            ImmutableSet.<SymbolAccess>builder()
