@Override
public PropertySetAbstractValue merge(PropertySetAbstractValue valA, PropertySetAbstractValue valB) {
    int maximumKnownCount = Math.max(valA.getKnownValuesCount(), valB.getKnownValuesCount());
    ArrayList<PropertySetAbstractValueKind> collector = new ArrayList<>(maximumKnownCount);

    for (int i = 0; i < maximumKnownCount; i++) {
        collector.add(combineKind(valA.get(i), valB.get(i)));
    }

    return PropertySetAbstractValue.getInstance(collector);
}

