    DuplicateDataFlowOperationVisitor operationProcessor = new DuplicateDataFlowOperationVisitor(analysisFrame);
    CopyAnalysis duplicateAnalysis = new CopyAnalysis(operationProcessor);
    return duplicateAnalysis.attemptGetOrCalculateResultCore(analysisFrame, true);
