private void processPotentialEscapeOperation(IOperation escapeOperation, Set<AbstractLocation> escapedTargets) {
    for (AbstractLocation escapedTarget : escapedTargets) {
        DisposeAbstractValue currentDisposeData = CurrentAnalysisState.get(escapedTarget);
        if (currentDisposeData != null && currentDisposeData.getKind() != DisposeAbstractValueKind.UNKNOWN) {
            DisposeAbstractValue updatedDisposeData = currentDisposeData.withNewEscapeOperation(escapeOperation);
            setAbstractValue(escapedTarget, updatedDisposeData);
        }
    }
}

