private boolean hasResourceOwnershipChangeInConstructorParam(IMethodSymbol enclosingMethod) {
    return enclosingMethod.getMethodKind() == MethodKind.CONSTRUCTOR &&
           enclosingMethod.getParameters().stream()
               .anyMatch(parameter -> resourceOwnershipTransferCandidateTypes.contains(parameter.getType()));
}

public boolean containsAnyResourceCreationDescendant(ImmutableList<IOperation> operationGroups, IMethodSymbol enclosingMethod) {
    return hasAnyOperationDescendant(operationGroups, this::isResourceCreation) ||
           hasResourceOwnershipChangeInConstructorParam(enclosingMethod);
}

public boolean isResourceCreationOrResourceOwnershipChange(AbstractLocation location, IMethodSymbol enclosingMethod) {
    if (location.getCreation() == null) {
        return location.getSymbol() != null &&
               location.getSymbol().getKind() == SymbolKind.PARAMETER &&
               hasResourceOwnershipChangeInConstructorParam(enclosingMethod);
    }

    return isResourceCreation(location.getCreation());
}

