public static ControlFlowConditionKind invert(ControlFlowConditionKind flowConditionType) {
    switch (flowConditionType) {
        case WHEN_FALSE:
            return ControlFlowConditionKind.WHEN_TRUE;

        case WHEN_TRUE:
            return ControlFlowConditionKind.WHEN_FALSE;

        default:
            System.err.println("Unsupported conditional kind: " + flowConditionType);
            return flowConditionType;
    }
}

public static List<IOperation> childOperations(ControlFlowRegion controlFlowArea, ControlFlowGraph cfg) {
    List<IOperation> output = new ArrayList<>();
    for (int index = controlFlowArea.getFirstBlockOrdinal(); index <= controlFlowArea.getLastBlockOrdinal(); index++) {
        BasicBlock block = cfg.getBlocks().get(index);
        output.addAll(block.descendantOperations());
    }
    return output;
}

