void handleNamespace(INamespaceSymbol namespaceItem) {
    for (INamespaceOrTypeSymbol member : namespaceItem.getMembers()) {
        if (member.getKind() == SymbolKind.NAMESPACE) {
            handleNamespace((INamespaceSymbol) member);
        } else if (namespaceItem.isGlobalNamespace()) {
            includeRootNamespace = true;
        } else if (!member.isImplicitlyDeclared()) {
            namespacesWithTypeElements.add(namespaceItem);
        }
    }
}

