private static int computeMaintainabilityScore(ComputationalComplexityMetrics computationComplexityMetrics, int cycleComplexity) {
    double computationalComplexityVolume = Math.max(0.0, Math.log(computationComplexityMetrics.getVolume())); // avoid Log(0) = -Infinity
    double logEffectiveLinesOfCode = Math.max(0.0, Math.log(computationComplexityMetrics.getEffectiveLinesOfCode())); // avoid Log(0) = -Infinity

    double rawMI = 171 - 5.2 * computationalComplexityVolume - 0.23 * cycleComplexity - 16.2 * logEffectiveLinesOfCode;

    return MetricsHelper.normalizeAndRoundMaintainabilityIndex(rawMI);
}

