static void excludeContainingTypes(ISymbol symbol, Set<INamedTypeSymbol> associatedTypesBuilder) {
    INamedTypeSymbol typeSymbol = (symbol instanceof INamedTypeSymbol) 
                                 ? (INamedTypeSymbol) symbol 
                                 : symbol.getContainingType();
    while (typeSymbol != null) {
        associatedTypesBuilder.remove(typeSymbol);
        typeSymbol = typeSymbol.getContainingType();
    }
}

static List<IParameterSymbol> obtainParameters(ISymbol member) {
    switch (member.getKind()) {
        case METHOD:
            return ((IMethodSymbol) member).getParameters();
        case PROPERTY:
            return ((IPropertySymbol) member).getParameters();
        default:
            return Collections.emptyList();
    }
}

